{
  "name": "@softprobe/opencode-plugin",
  "version": "0.1.17",
  "description": "OpenCode plugin that sends session telemetry to Softprobe",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "lint": "tsc -p tsconfig.json --noEmit"
  },
  "dependencies": {
    "@softprobe/tracing": "0.1.17"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.0",
    "@opentelemetry/api": "^1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.13",
    "@opentelemetry/api": "^1.9.0",
    "@opentelemetry/sdk-trace-base": "^1.30.1",
    "@types/node": "^22.13.10",
    "typescript": "^5.8.2",
    "vitest": "^3.0.8"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "keywords": [
    "softprobe",
    "opencode",
    "plugin",
    "observability",
    "opentelemetry"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/softprobe/softprobe-js.git",
    "directory": "packages/opencode-plugin"
  },
  "license": "MIT"
}
